package corpus.iteratorhasnext

class AdvancingIterator : Iterator<Int> {
    private var value = 0
    override fun hasNext(): Boolean = next() >= 0
    override fun next(): Int = value++
}

package corpus.iteratorhasnext

class BoundedIterator : Iterator<Int> {
    private var value = 0
    override fun hasNext(): Boolean = value < 2
    override fun next(): Int {
        if (!hasNext()) throw NoSuchElementException()
        return value++
    }
}

