package corpus.iteratorhasnext

class HelperIterator : Iterator<Int> {
    private var value = 0
    override fun hasNext(): Boolean = remaining()
    override fun next(): Int = read()
    private fun remaining(): Boolean = value < 2
    private fun read(): Int {
        if (!remaining()) throw NoSuchElementException()
        return value++
    }
}

package corpus.iteratorhasnext

class ConstantIterator : Iterator<Int> {
    override fun hasNext(): Boolean = listOf(1).iterator().next() == 1
    override fun next(): Int = 1
}

package corpus.iteratorhasnext

interface Iterator<T> {
    fun hasNext(): Boolean
    fun next(): T
}

class StatelessProbe : Iterator<Int> {
    override fun hasNext(): Boolean = next() == 1
    override fun next(): Int = 1
}
